(function() {
    'use strict';

    class CoachingAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'El Gerente que Desarrolla';
            this.version = '1.1.0';
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0 || !state.history || state.history.length === 0) {
                state.domainState = {
                    growScore: 0,
                    growTotal: 0,
                    sbiScore: -1,
                    idpScore: -1,
                    coachingConversations: 0,
                    totalConversations: 0,
                    retentionScore: -1,
                    directiveCount: 0,
                    coachingCount: 0,
                    growHistory: [],
                    consistencyHistory: [],
                    overallHistory: [],
                    randomEvents: {
                        r2: Math.random() < 0.35 ? 'vip_complaint' : 'none',
                        r3_marcos_gossip: Math.random() < 0.25,
                        r3_ernesto_call: Math.random() < 0.30,
                        r3_roberto_offer: Math.random() < 0.20
                    },
                    robertoEngagement: 'neutral'
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {};
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            // NOTE: must NOT re-render the panel here — doing so wipes the user's
            // current radio/checkbox selections before we read them. Read-only.
            var round = window.mySimulation.state.currentPeriod || 1;
            var t = window.mySimulation.t.bind(window.mySimulation);

            if (round === 1) {
                var d1 = document.querySelector('input[name="d1"]:checked');
                var d2 = document.querySelector('input[name="d2"]:checked');
                var d3 = document.querySelector('input[name="d3"]:checked');
                if (!d1 || !d2 || !d3) {
                    window.mySimulation.uiManager.showNotification(t('all_required'), 'warning');
                    return false;
                }
                decisions.d1 = d1.value;
                decisions.d2 = d2.value;
                decisions.d3 = d3.value;
            } else if (round === 2) {
                var d4 = document.querySelector('input[name="d4"]:checked');
                var d6 = document.querySelector('input[name="d6"]:checked');
                var d7 = document.querySelector('input[name="d7"]:checked');
                var d5checks = document.querySelectorAll('input[name="d5"]:checked');
                if (!d4 || !d6 || !d7) {
                    window.mySimulation.uiManager.showNotification(t('all_required'), 'warning');
                    return false;
                }
                if (d5checks.length !== 3) {
                    window.mySimulation.uiManager.showNotification(t('idp_select_3'), 'warning');
                    return false;
                }
                decisions.d4 = d4.value;
                decisions.d5 = [];
                d5checks.forEach(function(c) { decisions.d5.push(c.value); });
                decisions.d6 = d6.value;
                decisions.d7 = d7.value;
            } else if (round === 3) {
                var d8 = document.querySelector('input[name="d8"]:checked');
                var d9 = document.querySelector('input[name="d9"]:checked');
                var d10 = document.querySelector('input[name="d10"]:checked');
                if (!d8 || !d9 || !d10) {
                    window.mySimulation.uiManager.showNotification(t('all_required'), 'warning');
                    return false;
                }
                decisions.d8 = d8.value;
                decisions.d9 = d9.value;
                decisions.d10 = d10.value;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;
            var results = { period: round };

            if (round === 1) {
                var sbi = d.d1 === 'b' ? 3 : 0;
                ds.sbiScore = sbi;
                results.sbiScore = sbi;

                var cGrow = 0;
                if (d.d1 === 'b') cGrow += 1;
                if (d.d2 === 'b') cGrow += 2;
                if (d.d3 === 'b') cGrow += 1;
                ds.growScore += cGrow;
                ds.growTotal += 4;
                results.carlosGrow = cGrow;

                var cCoach = (d.d1 === 'b' && d.d3 === 'b') ? 1 : 0;
                ds.coachingConversations += cCoach;
                ds.totalConversations += 1;

                if (d.d1 === 'a') ds.directiveCount++;
                else if (d.d1 === 'b') ds.coachingCount++;
                if (d.d2 === 'a') ds.directiveCount++;
                else if (d.d2 === 'b') ds.coachingCount++;
                if (d.d3 === 'a' || d.d3 === 'c') ds.directiveCount++;
                else if (d.d3 === 'b') ds.coachingCount++;

            } else if (round === 2) {
                var yGrow = 0;
                if (d.d4 === 'b') yGrow = 4;
                else if (d.d4 === 'c') yGrow = 3;
                else yGrow = 0;
                ds.growScore += yGrow;
                ds.growTotal += 4;
                results.yolandaGrow = yGrow;

                var idpTags = { i: '10', ii: '70', iii: '20', iv: '70', v: '20', vi: '70' };
                var s70 = 0;
                var s20 = 0;
                var s10 = 0;
                if (d.d5 && d.d5.length) {
                    d.d5.forEach(function(opt) {
                        if (idpTags[opt] === '70') s70++;
                        else if (idpTags[opt] === '20') s20++;
                        else s10++;
                    });
                }
                var idpQ = s70 >= 2 ? 100 : (s70 === 1 ? 60 : 30);
                ds.idpScore = idpQ;
                results.idpScore = idpQ;
                results.idp70 = s70;
                results.idp20 = s20;
                results.idp10 = s10;

                var yCoach = (d.d4 === 'b' || d.d4 === 'c') ? 1 : 0;
                ds.coachingConversations += yCoach;
                ds.totalConversations += 1;

                var rGrow = 0;
                if (d.d6 === 'b') rGrow += 2;
                if (d.d7 === 'b') rGrow += 2;
                ds.growScore += rGrow;
                ds.growTotal += 4;
                results.robertoGrow = rGrow;

                var retS = 0;
                if (d.d6 === 'b') retS += 50;
                if (d.d7 === 'b') retS += 50;
                else if (d.d7 === 'a') retS += 20;
                ds.retentionScore = retS;
                results.retentionScore = retS;

                var rCoach = (d.d6 === 'b') ? 1 : 0;
                ds.coachingConversations += rCoach;
                ds.totalConversations += 1;

                ds.robertoEngagement = d.d6 === 'b' ? 'open' : (d.d6 === 'a' ? 'transactional' : 'guarded');

                if (d.d4 === 'a') ds.directiveCount++;
                else ds.coachingCount++;
                if (d.d6 === 'a') ds.directiveCount++;
                else if (d.d6 === 'b') ds.coachingCount++;
                else ds.directiveCount += 0.5;
                if (d.d7 === 'b') ds.coachingCount++;
                else ds.directiveCount++;

            } else if (round === 3) {
                var mCoach = d.d8 === 'b' ? 1 : 0;
                ds.coachingConversations += mCoach;
                ds.totalConversations += 1;

                if (d.d8 === 'a') ds.directiveCount++;
                else if (d.d8 === 'b') ds.coachingCount++;

                if (d.d9 === 'b') ds.coachingCount++;
                else if (d.d9 === 'a') ds.directiveCount += 0.5;

                if (d.d10 === 'a') ds.directiveCount++;
                else if (d.d10 === 'b') ds.coachingCount++;
                else ds.coachingCount += 0.5;
            }

            var growPct = ds.growTotal > 0 ? Math.round(ds.growScore / ds.growTotal * 100) : 0;
            var totalStyle = ds.coachingCount + ds.directiveCount;
            var stylePct = totalStyle > 0 ? Math.round(ds.coachingCount / totalStyle * 100) : 50;
            var conPct = ds.totalConversations > 0 ? Math.round(ds.coachingConversations / ds.totalConversations * 100) : 0;

            ds.growHistory.push(growPct);
            ds.consistencyHistory.push(conPct);
            ds.overallHistory.push(stylePct);

            results.growPct = growPct;
            results.consistencyPct = conPct;
            results.stylePct = stylePct;
            results.sbiDisplay = ds.sbiScore >= 0 ? ds.sbiScore + '/3' : '--';
            results.idpDisplay = ds.idpScore >= 0 ? ds.idpScore + '%' : '--';
            results.retentionDisplay = ds.retentionScore >= 0 ? ds.retentionScore + '%' : '--';

            // Defensive: expose the composite score on domainState for any framework/report
            // layer that reads it directly. Uses the SAME weights as getPerformanceSummary.
            var sbiPctF = ds.sbiScore >= 3 ? 100 : 0;
            var idpPctF = ds.idpScore >= 0 ? ds.idpScore : 0;
            var retPctF = ds.retentionScore >= 0 ? ds.retentionScore : 0;
            ds.totalScore = Math.round((growPct * 30 + sbiPctF * 20 + idpPctF * 20 + conPct * 20 + retPctF * 10) / 100);
            results.totalScore = ds.totalScore;

            var self = this;
            var maxP = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.maxPeriods) || 3;
            if (round < maxP) {
                setTimeout(function() {
                    self._updateBriefing({ currentPeriod: round + 1, domainState: ds });
                }, 500);
            }

            return results;
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('growDisplay', 'results.growPct', function(v) { return v + '%'; });
            uiManager.bind('sbiDisplay', 'results.sbiDisplay');
            uiManager.bind('idpDisplay', 'results.idpDisplay');
            uiManager.bind('consistencyDisplay', 'results.consistencyPct', function(v) { return v + '%'; });
            uiManager.bind('retentionDisplay', 'results.retentionDisplay');
        }

        getChartConfig() {
            return {
                coachingChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'GROW Completion %',
                            data: [],
                            borderColor: '#27ae60',
                            backgroundColor: 'rgba(39,174,96,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3
                        }, {
                            label: 'Coaching Style %',
                            data: [],
                            borderColor: '#2980b9',
                            backgroundColor: 'rgba(41,128,185,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3
                        }, {
                            label: 'Consistency %',
                            data: [],
                            borderColor: '#e67e22',
                            backgroundColor: 'rgba(230,126,34,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'Coaching Performance Over Rounds' } },
                        scales: { y: { beginAtZero: true, max: 100, ticks: { callback: function(v) { return v + '%'; } } } }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.growHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                coachingChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.growHistory },
                        { data: state.domainState.overallHistory },
                        { data: state.domainState.consistencyHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k){ return k; };
            if (!history.length) return { totalPeriods: 0 };
            var last = history[history.length - 1];
            var r = last.results || {};

            var growPct = r.growPct || 0;
            var sbiPct = (r.sbiDisplay === '3/3') ? 100 : 0;
            var idpPct = r.idpDisplay && r.idpDisplay !== '--' ? parseInt(r.idpDisplay) : 0;
            var conPct = r.consistencyPct || 0;
            var retPct = r.retentionDisplay && r.retentionDisplay !== '--' ? parseInt(r.retentionDisplay) : 0;

            var weighted = (growPct * 30 + sbiPct * 20 + idpPct * 20 + conPct * 20 + retPct * 10) / 100;

            var performance = t('tier_apprentice');
            if (weighted >= 80) performance = t('tier_exemplary');
            else if (weighted >= 60) performance = t('tier_developing');
            else if (weighted >= 40) performance = t('tier_transition');

            var insights = [];
            if (growPct < 75) insights.push(t('insight_grow'));
            if (conPct < 75) insights.push(t('insight_consistency'));
            if (idpPct < 60) insights.push(t('insight_idp'));
            if (retPct < 50) insights.push(t('insight_retention'));
            if (insights.length === 0) insights.push(t('insight_excellent'));

            return {
                totalScore: Math.round(weighted),
                totalPeriods: history.length,
                performance: performance,
                scoreBreakdown: { grow: growPct, sbi: sbiPct, idp: idpPct, consistency: conPct, retention: retPct },
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k){ return k; };
            var b = summary.scoreBreakdown || {};
            function row(label, val) {
                return '<div style="display:flex;justify-content:space-between;padding:4px 0;border-bottom:1px solid #eee;">' +
                       '<span style="color:#555;">' + label + '</span><strong>' + val + '</strong></div>';
            }
            var rows = row(t('grow_label'), (b.grow != null ? b.grow : 0) + '%') +
                       row(t('sbi_label'), (b.sbi != null ? b.sbi : 0) + '%') +
                       row(t('idp_label'), (b.idp != null ? b.idp : 0) + '%') +
                       row(t('consistency_label'), (b.consistency != null ? b.consistency : 0) + '%') +
                       row(t('retention_label'), (b.retention != null ? b.retention : 0) + '%');
            var insights = (summary.insights || []).map(function(i) { return '<li style="margin-bottom:6px;">' + i + '</li>'; }).join('');
            return '<div style="text-align:center;padding:10px;">' +
                   '<div style="font-size:0.8rem;text-transform:uppercase;letter-spacing:1px;color:#888;">' + t('final_score_label') + '</div>' +
                   '<div style="font-size:3rem;font-weight:700;color:#2c3e50;line-height:1.1;">' + (summary.totalScore != null ? summary.totalScore : 0) + '<span style="font-size:1.2rem;color:#888;">/100</span></div>' +
                   '<div style="font-size:1.15rem;font-weight:600;color:#27ae60;margin-bottom:18px;">' + (summary.performance || '') + '</div>' +
                   '<div style="max-width:420px;margin:0 auto 18px;text-align:left;">' + rows + '</div>' +
                   (insights ? '<div style="max-width:480px;margin:0 auto;text-align:left;"><h5 style="margin-bottom:8px;">' + t('takeaways_label') + '</h5><ul style="padding-left:20px;margin:0;">' + insights + '</ul></div>' : '') +
                   '</div>';
        }

        getHint(state, results) {
            var t = window.mySimulation.t.bind(window.mySimulation);
            if (state.currentPeriod === 1) {
                if (results.sbiScore < 3) return t('hint_sbi');
                if (results.carlosGrow < 3) return t('hint_grow_carlos');
            }
