        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, 2);
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };

            var briefEl = document.getElementById('briefingText');
            var titleEl = document.getElementById('briefingTitle');
            var decisionsEl = document.getElementById('decisionsPanel');
            var eventEl = document.getElementById('eventAlert');
            var eventTextEl = document.getElementById('eventText');

            if (!briefEl || !decisionsEl) return;

            if (eventEl) eventEl.style.display = 'none';
            var ds = state.domainState || {};

            if (idx === 0) {
                if (titleEl) titleEl.innerHTML = t('r1_title');
                briefEl.innerHTML = t('r1_briefing');
                decisionsEl.innerHTML =
                    this._buildRadio('d1', t('r1_d1_label'), [
                        { value: 'a', text: t('r1_d1_a') },
                        { value: 'b', text: t('r1_d1_b') },
                        { value: 'c', text: t('r1_d1_c') }
                    ]) +
                    this._buildRadio('d2', t('r1_d2_label'), [
                        { value: 'a', text: t('r1_d2_a') },
                        { value: 'b', text: t('r1_d2_b') },
                        { value: 'c', text: t('r1_d2_c') }
                    ]) +
                    this._buildRadio('d3', t('r1_d3_label'), [
                        { value: 'a', text: t('r1_d3_a') },
                        { value: 'b', text: t('r1_d3_b') },
                        { value: 'c', text: t('r1_d3_c') }
                    ]);
            } else if (idx === 1) {
                if (titleEl) titleEl.innerHTML = t('r2_title');
                briefEl.innerHTML = t('r2_briefing');
                if (ds.randomEvents && ds.randomEvents.r2 === 'vip_complaint' && eventEl && eventTextEl) {
                    eventEl.style.display = 'flex';
                    eventTextEl.innerHTML = t('event_vip_complaint');
                }
                decisionsEl.innerHTML =
                    '<h4>' + t('r2_yolanda_heading') + '</h4>' +
                    this._buildRadio('d4', t('r2_d4_label'), [
                        { value: 'a', text: t('r2_d4_a') },
                        { value: 'b', text: t('r2_d4_b') },
                        { value: 'c', text: t('r2_d4_c') }
                    ]) +
                    this._buildCheckbox('d5', t('r2_d5_label'), [
                        { value: 'i', text: t('r2_d5_i') },
                        { value: 'ii', text: t('r2_d5_ii') },
                        { value: 'iii', text: t('r2_d5_iii') },
                        { value: 'iv', text: t('r2_d5_iv') },
                        { value: 'v', text: t('r2_d5_v') },
                        { value: 'vi', text: t('r2_d5_vi') }
                    ]) +
                    '<h4>' + t('r2_roberto_heading') + '</h4>' +
                    this._buildRadio('d6', t('r2_d6_label'), [
                        { value: 'a', text: t('r2_d6_a') },
                        { value: 'b', text: t('r2_d6_b') },
                        { value: 'c', text: t('r2_d6_c') }
                    ]) +
                    this._buildRadio('d7', t('r2_d7_label'), [
                        { value: 'a', text: t('r2_d7_a') },
                        { value: 'b', text: t('r2_d7_b') },
                        { value: 'c', text: t('r2_d7_c') }
                    ]);
                this._wireIdpCounter();
            } else if (idx === 2) {
                if (titleEl) titleEl.innerHTML = t('r3_title');
                briefEl.innerHTML = t('r3_briefing');
                if (ds.randomEvents && eventEl && eventTextEl) {
                    var msgs = [];
                    if (ds.randomEvents.r3_marcos_gossip) msgs.push(t('event_marcos_gossip'));
                    if (ds.randomEvents.r3_ernesto_call) msgs.push(t('event_ernesto_call'));
                    if (ds.randomEvents.r3_roberto_offer) msgs.push(t('event_roberto_offer'));
                    if (msgs.length > 0) {
                        eventEl.style.display = 'flex';
                        eventTextEl.innerHTML = msgs.join('<br><br>');
                    }
                }
                decisionsEl.innerHTML =
                    '<h4>' + t('r3_marcos_heading') + '</h4>' +
                    this._buildRadio('d8', t('r3_d8_label'), [
                        { value: 'a', text: t('r3_d8_a') },
                        { value: 'b', text: t('r3_d8_b') },
                        { value: 'c', text: t('r3_d8_c') }
                    ]) +
                    this._buildRadio('d9', t('r3_d9_label'), [
                        { value: 'a', text: t('r3_d9_a') },
                        { value: 'b', text: t('r3_d9_b') },
                        { value: 'c', text: t('r3_d9_c') }
                    ]) +
                    '<h4>' + t('r3_mediation_heading') + '</h4>' +
                    this._buildRadio('d10', t('r3_d10_label'), [
                        { value: 'a', text: t('r3_d10_a') },
                        { value: 'b', text: t('r3_d10_b') },
                        { value: 'c', text: t('r3_d10_c') }
                    ]);
            }

            var total = (ds.coachingCount || 0) + (ds.directiveCount || 0);
            var pct = total > 0 ? Math.round((ds.coachingCount || 0) / total * 100) : 50;
            var meterFill = document.getElementById('styleMeterFill');
            if (meterFill) meterFill.style.left = pct + '%';
        }

        _wireIdpCounter() {
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var boxes = document.querySelectorAll('input[name="d5"]');
            var counter = document.getElementById('idpCounter');
            if (!boxes.length) return;
            var update = function() {
                var n = document.querySelectorAll('input[name="d5"]:checked').length;
                if (counter) {
                    counter.textContent = t('idp_counter').replace('{n}', n);
                    counter.className = 'coaching-sim-idp-counter' + (n === 3 ? ' complete' : '');
                }
                boxes.forEach(function(b) { if (!b.checked) b.disabled = (n >= 3); });
            };
            boxes.forEach(function(b) { b.addEventListener('change', update); });
            update();
        }

        _buildRadio(name, label, options) {
            var html = '<fieldset class="coaching-sim-decision-group">';
            html += '<legend class="coaching-sim-decision-label">' + label + '</legend>';
            for (var i = 0; i < options.length; i++) {
                var oid = name + '_' + options[i].value;
                html += '<div class="coaching-sim-option">';
                html += '<label for="' + oid + '"><input type="radio" id="' + oid + '" name="' + name + '" value="' + options[i].value + '"> ' + options[i].text + '</label>';
                html += '</div>';
            }
            html += '</fieldset>';
            return html;
        }

        _buildCheckbox(name, label, options) {
            var html = '<fieldset class="coaching-sim-decision-group">';
            html += '<legend class="coaching-sim-decision-label">' + label + '</legend>';
            html += '<div class="coaching-sim-idp-counter" id="idpCounter" aria-live="polite"></div>';
            for (var i = 0; i < options.length; i++) {
                var oid = name + '_' + options[i].value;
                html += '<div class="coaching-sim-option">';
                html += '<label for="' + oid + '"><input type="checkbox" id="' + oid + '" name="' + name + '" value="' + options[i].value + '"> ' + options[i].text + '</label>';
                html += '</div>';
            }
            html += '</fieldset>';
            return html;
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new CoachingAdapter(), {
            simulationType: 'coaching_manager_345',
            maxPeriods: 3,
            autoSaveInterval: 30000
        });
    });

})();
